package com.nequard.maintenance;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="work_orders") public class WorkOrder{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;@Column(nullable=false)String title;String priority="MEDIUM",status="OPEN",recommendation;UUID deviceId;Instant createdAt=Instant.now();public UUID getId(){return id;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getPriority(){return priority;}public void setPriority(String v){priority=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getRecommendation(){return recommendation;}public void setRecommendation(String v){recommendation=v;}public UUID getDeviceId(){return deviceId;}public void setDeviceId(UUID v){deviceId=v;}public Instant getCreatedAt(){return createdAt;}}
